import { describe, test, expect } from "vitest";
import { TaskManager } from "../src/task-manager.ts";

describe("Update invariant tests", () => {
  test("update with empty object preserves all fields", () => {
    const tm = new TaskManager();
    const t = tm.createTask({
      title: "Full",
      priority: 5,
      description: "Desc",
      status: "in_progress",
      dueDate: "2024-06-15",
    });
    const originalUpdatedAt = t.updatedAt;
    const updated = tm.updateTask(t.id, {});
    expect(updated.title).toBe("Full");
    expect(updated.description).toBe("Desc");
    expect(updated.priority).toBe(5);
    expect(updated.status).toBe("in_progress");
    expect(updated.dueDate).toBe("2024-06-15");
    expect(updated.updatedAt).not.toBe(originalUpdatedAt);
  });

  test("update can explicitly set dueDate to null", () => {
    const tm = new TaskManager();
    const t = tm.createTask({
      title: "t",
      priority: 1,
      dueDate: "2024-01-01",
    });
    const updated = tm.updateTask(t.id, { dueDate: null });
    expect(updated.dueDate).toBeNull();
    expect(updated.title).toBe("t");
    expect(updated.priority).toBe(1);
  });

  test("update can explicitly set description to empty string", () => {
    const tm = new TaskManager();
    const t = tm.createTask({
      title: "t",
      priority: 1,
      description: "Has desc",
    });
    const updated = tm.updateTask(t.id, { description: "" });
    expect(updated.description).toBe("");
    expect(updated.title).toBe("t");
  });

  test("update only priority preserves all other fields", () => {
    const tm = new TaskManager();
    const t = tm.createTask({
      title: "t",
      priority: 1,
      description: "d",
      status: "archived",
      dueDate: "2025-12-31",
    });
    const updated = tm.updateTask(t.id, { priority: 5 });
    expect(updated.priority).toBe(5);
    expect(updated.title).toBe("t");
    expect(updated.description).toBe("d");
    expect(updated.status).toBe("archived");
    expect(updated.dueDate).toBe("2025-12-31");
  });

  test("concurrent updates preserve fields from each other", () => {
    const tm = new TaskManager();
    const t = tm.createTask({
      title: "Original",
      priority: 1,
      description: "Desc",
      status: "pending",
      dueDate: "2024-01-01",
    });
    // Simulate rapid sequential updates
    const u1 = tm.updateTask(t.id, { title: "Updated1" });
    const u2 = tm.updateTask(t.id, { priority: 3 });
    const u3 = tm.updateTask(t.id, { status: "completed" });
    const final = tm.getTask(t.id);
    expect(final?.title).toBe("Updated1");
    expect(final?.priority).toBe(3);
    expect(final?.status).toBe("completed");
    expect(final?.description).toBe("Desc");
    expect(final?.dueDate).toBe("2024-01-01");
  });

  test("multiple field update only overwrites specified fields", () => {
    const tm = new TaskManager();
    const t = tm.createTask({
      title: "t",
      priority: 1,
      description: "d",
      status: "pending",
      dueDate: "2024-01-01",
    });
    const updated = tm.updateTask(t.id, { title: "new", priority: 4 });
    expect(updated.title).toBe("new");
    expect(updated.priority).toBe(4);
    expect(updated.description).toBe("d");
    expect(updated.status).toBe("pending");
    expect(updated.dueDate).toBe("2024-01-01");
  });

  test("update returns a copy, not a reference to internal state", () => {
    const tm = new TaskManager();
    const t = tm.createTask({ title: "t", priority: 1 });
    const updated = tm.updateTask(t.id, { title: "u" });
    updated.title = "mutated";
    const refetched = tm.getTask(t.id);
    expect(refetched?.title).toBe("u");
  });

  test("getTask returns copy, mutations do not affect internal state", () => {
    const tm = new TaskManager();
    const t = tm.createTask({ title: "t", priority: 1 });
    const copy = tm.getTask(t.id);
    if (copy) copy.title = "mutated";
    const refetched = tm.getTask(t.id);
    expect(refetched?.title).toBe("t");
  });

  test("listTasks returns copies that do not affect internal state", () => {
    const tm = new TaskManager();
    tm.createTask({ title: "a", priority: 1 });
    const list = tm.listTasks();
    list[0]!.title = "mutated";
    const refetched = tm.listTasks();
    expect(refetched[0]!.title).toBe("a");
  });

  test("filterByStatus returns copies that do not affect internal state", () => {
    const tm = new TaskManager();
    tm.createTask({ title: "a", priority: 1, status: "pending" });
    const filtered = tm.filterByStatus("pending");
    filtered[0]!.title = "mutated";
    const refetched = tm.filterByStatus("pending");
    expect(refetched[0]!.title).toBe("a");
  });

  test("update throws for non-existent task", () => {
    const tm = new TaskManager();
    expect(() => tm.updateTask("nonexistent", { title: "x" })).toThrow();
  });

  test("delete throws for non-existent task", () => {
    const tm = new TaskManager();
    expect(() => tm.deleteTask("nonexistent")).toThrow();
  });

  test("createTask with dueDate null is stored as null", () => {
    const tm = new TaskManager();
    const t = tm.createTask({ title: "t", priority: 1, dueDate: null });
    expect(t.dueDate).toBeNull();
  });
});

