    expect(updated.title).toBe("t");
    expect(updated.priority).toBe(1);
  });

  test("update can explicitly set description to empty string", () => {
    const tm = new TaskManager();
    const t = tm.createTask({
      title: "t",
      priority: 1,
      description: "Has desc",
    });
    const updated = tm.updateTask(t.id, { description: "" });
    expect(updated.description).toBe("");
    expect(updated.title).toBe("t");
  });

  test("update only priority preserves all other fields", () => {
    const tm = new TaskManager();
    const t = tm.createTask({
      title: "t",
      priority: 1,
      description: "d",
      status: "archived",
      dueDate: "2025-12-31",
    });
    const updated = tm.updateTask(t.id, { priority: 5 });
    expect(updated.priority).toBe(5);
    expect(updated.title).toBe("t");
    expect(updated.description).toBe("d");
    expect(updated.status).toBe("archived");
    expect(updated.dueDate).toBe("2025-12-31");
  });

  test("concurrent updates preserve fields from each other", () => {
    const tm = new TaskManager();
