const tm = new TaskManager();

// Create a task with multiple fields populated
const task = tm.createTask({
  title: "Original Title",
  priority: 3,
  description: "Original Description",
  status: "in_progress",
  dueDate: "2024-12-31",
});

console.log("=== Created Task ===");
console.log(task);

// Update only the title - other fields should remain unchanged
const updated = tm.updateTask(task.id, { title: "Updated Title" });

console.log("\n=== After Updating Only Title ===");
console.log(updated);

// Check for the bug
const failures: string[] = [];

if (updated.title !== "Updated Title") {
  failures.push(`Title: expected "Updated Title", got "${updated.title}"`);
}
if (updated.description !== "Original Description") {
  failures.push(`Description: expected "Original Description", got ${JSON.stringify(updated.description)}`);
}
if (updated.priority !== 3) {
  failures.push(`Priority: expected 3, got ${updated.priority}`);
}
if (updated.status !== "in_progress") {
  failures.push(`Status: expected "in_progress", got ${JSON.stringify(updated.status)}`);
}
if (updated.dueDate !== "2024-12-31") {
  failures.push(`DueDate: expected "2024-12-31", got ${JSON.stringify(updated.dueDate)}`);
}

if (failures.length > 0) {
  console.log("\n=== BUG DETECTED - Fields erased by update ===");
  for (const f of failures) {
    console.log(`  ❌ ${f}`);
  }
  process.exit(1);
} else {
  console.log("\n=== All fields preserved correctly ===");
  process.exit(0);
}

